<?php
$e = static fn (mixed $value): string => App\Core\View::e($value);
$base = App\Core\Config::url('/campeonatos/' . $championship['slug']);
$initials = static function (string $name): string { $parts = preg_split('/\s+/', trim($name)) ?: []; $value = ''; foreach (array_slice($parts, 0, 2) as $part) $value .= strtoupper(substr($part, 0, 1)); return $value ?: 'AT'; };
?>
<section class="portal-page-heading team-page-heading"><p class="eyebrow"><?= $e($championship['name']) ?></p><?php if ($team['shield_path']): ?><img class="portal-shield portal-shield-large" src="<?= $e($base . '/equipes/' . rawurlencode($team['slug']) . '/escudo') ?>" alt="Escudo de <?= $e($team['name']) ?>"><?php else: ?><span class="team-mark-fallback portal-shield-large" data-icon="shield" aria-label="Escudo provisório de <?= $e($team['name']) ?>"></span><?php endif; ?><h1><?= $e($team['name']) ?></h1><p><?= $e($team['description'] ?: trim(($team['city'] ?: '') . ' ' . ($team['state'] ?: ''))) ?></p></section>
<section><div class="section-heading"><div><p class="eyebrow">Elenco oficial</p><h2><?= (int) $team['athletes_total'] ?> atletas elegíveis</h2></div><a href="<?= $e($base . '/atletas') ?>">Todos os atletas</a></div><div class="portal-card-grid team-roster-grid"><?php foreach ($team['athletes'] as $athlete): ?><a class="portal-card" href="<?= $e($base . '/atletas/' . $athlete['id']) ?>"><?php if ($athlete['photo_path']): ?><img class="portal-athlete-photo" src="<?= $e($base . '/atletas/' . $athlete['id'] . '/foto') ?>" alt="Foto de <?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?>"><?php else: ?><span class="athlete-avatar-fallback" aria-label="Avatar provisório de <?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?>"><?= $e($initials((string) ($athlete['sporting_name'] ?: $athlete['full_name']))) ?></span><?php endif; ?><h2><?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?></h2><p><?= $e($athlete['position_name']) ?> · <?= $e($athlete['preferred_number'] ?: 'Sem número') ?></p></a><?php endforeach; ?></div><?php if (!$team['athletes']): ?><p>Elenco oficial ainda não publicado.</p><?php endif; ?><?php if (($pages ?? 1) > 1): ?><nav class="pagination" aria-label="Paginação do elenco"><?php for ($index = 1; $index <= $pages; $index++): ?><a class="<?= $index === $page ? 'active' : '' ?>" href="<?= $e($base . '/equipes/' . rawurlencode($team['slug']) . '?page=' . $index) ?>"><?= $index ?></a><?php endfor; ?></nav><?php endif; ?></section>
